#!/usr/bin/env python3
"""Compare data/guidebook.db against a rebuilt DB: tables, views, triggers, row counts, user_version."""
import sqlite3, sys

a_path, b_path = sys.argv[1], sys.argv[2]
EXEMPT = {"pipeline_runs"}


def load(p):
    c = sqlite3.connect(f"file:{p}?mode=ro", uri=True)
    objs = {}
    for t, n in c.execute("select type,name from sqlite_master where type in ('table','view','trigger') and name not like 'sqlite_%'"):
        objs.setdefault(t, set()).add(n)
    counts = {}
    for n in objs.get("table", set()):
        counts[n] = c.execute(f'select count(*) from "{n}"').fetchone()[0]
    uv = c.execute("pragma user_version").fetchone()[0]
    return objs, counts, uv


ao, ac, auv = load(a_path)
bo, bc, buv = load(b_path)
print(f"user_version: committed={auv} rebuilt={buv}")
bad = 0
for k in ("table", "view", "trigger"):
    sa, sb = ao.get(k, set()), bo.get(k, set())
    print(f"{k}s: committed={len(sa)} rebuilt={len(sb)} only_committed={sorted(sa - sb)} only_rebuilt={sorted(sb - sa)}")
    if sa != sb:
        bad += 1
diff = {n: (ac[n], bc[n]) for n in ac if n in bc and ac[n] != bc[n]}
print("row-count differences:", diff)
nonexempt = {n: v for n, v in diff.items() if n not in EXEMPT}
print("non-exempt row-count differences:", nonexempt)
print("RESULT:", "OK" if not nonexempt and not bad and auv == buv else "DIFFERS")

