"""Remove a top-level list entry '- id: <id>' (and its indented body, and any comment lines directly preceding
it that begin at column 0 with '#') from a YAML registry as TEXT. Prints removed line range."""
import re, sys
path, ident = sys.argv[1], sys.argv[2]
lines = open(path).read().split('\n')
start = None
for i, l in enumerate(lines):
    if l == f'- id: {ident}':
        start = i; break
if start is None:
    sys.exit(f'NOT FOUND: {ident}')
end = len(lines)
for j in range(start + 1, len(lines)):
    l = lines[j]
    # next top-level item: '- ' at col 0, a col-0 key, or a col-0 comment
    if re.match(r'^(- |[A-Za-z_#])', l):
        end = j; break
# leading comment lines immediately above start belong to this entry only if they are col-0 '#' lines
s = start
while s > 0 and lines[s-1].startswith('#'):
    s -= 1
if s != start:
    print(f'NOTE: {start-s} leading comment line(s) removed with entry:', file=sys.stderr)
    for k in range(s, start): print('   ', lines[k][:120], file=sys.stderr)
print(f'{ident}: removed lines {s+1}-{end} ({end-s} lines)')
del lines[s:end]
open(path, 'w').write('\n'.join(lines))
EOF
